mapper.select:
SELECT COUNT(*)
FROM login_log l
WHERE l.login_name = #{loginName}
  AND l.portal_type = #{portalType}
  AND l.result = 'failure'
  AND l.fail_reason = 'password_mismatch'
  AND l.created_at >= #{since}
  AND l.created_at > COALESCE((
      SELECT MAX(s.created_at)
      FROM login_log s
      WHERE s.login_name = #{loginName}
        AND s.portal_type = #{portalType}
        AND s.result = 'success'
  ), #{since})
